def generate_inputs(device):
    x = torch.zeros(16, 16384, device=device, dtype=torch.float32)
    # Set alternating high-magnitude values at positions likely affected by the bug
    for b in range(16):
        for i in range(16384):
            if i % 4 == 3:
                x[b, i] = 100.0  # idx+3 positions
            elif i % 4 == 0:
                x[b, i] = -100.0  # idx+4 positions (next group's start)
            else:
                x[b, i] = 0.001  # small values to not dominate L1 norm
    return [x]
